    String baseUrl = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    HttpProtocolBuilder httpProtocol =
      http.baseUrl(baseUrl)
          .disableFollowRedirect()
          .header("Content-Type", "application/json")
          .acceptHeader("application/json");

    List<Map<String, ?>> credentials = new ArrayList<>();
    for (int i = 1; i <= 16; i++) {
      Map<String, Object> c = new HashMap<>();
      c.put("username", "bench-" + i);
      c.put("password", "bench");
      credentials.add(c);
    }

    FeederBuilder<?> credFeeder = listFeeder(credentials).circular();

    ChainBuilder login =
      exec(http("Login Form")
        .get("/v2/login-form")
        .check(status().is(200))
        .check(css("input[name='csrf']", "value").saveAs("csrf")))
      .exec(http("Login")
        .post("/v2/login")
        .body(StringBody("{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{csrf}\"}"))
        .check(status().saveAs("loginStatus"))
        .check(header("Location").optional().saveAs("loginLocation"))
        .check(jsonPath("$.csrf").optional().saveAs("loginCsrf")))
      .doIf(session -> session.getInt("loginStatus") == 302)
        .then(
          exec(http("Follow Login Redirect")
            .get(session -> session.getString("loginLocation"))
            .check(status().is(200))
            .check(jsonPath("$.csrf").optional().saveAs("loginCsrf"))))
      .exec(session -> {
          if (session.contains("loginCsrf") && session.getString("loginCsrf") != null) {
            session = session.set("csrf", session.getString("loginCsrf"));
          }
          return session;
      });

    ChainBuilder work =
      exec(session -> session.set("workAttempt", 0).set("workStatus", 429))
        .asLongAs(session -> session.getInt("workStatus") == 429 && session.getInt("workAttempt") < 5)
        .on(
          exec(session -> session.set("workAttempt", session.getInt("workAttempt") + 1))
          .exec(http("Work")
            .post("/v2/work")
            .header("X-CSRF-Token", session -> session.getString("csrf"))
            .body(StringBody("{}"))
            .check(status().in(200, 429, 401).saveAs("workStatus"))
            .check(header("Retry-After").optional().saveAs("retryAfter"))
            .check(jsonPath("$.csrf").optional().saveAs("workCsrf")))
          .doIf(session -> session.getInt("workStatus") == 429 && session.getInt("workAttempt") < 5)
            .then(pause(Duration.ofSeconds(1)))
          .exec(session -> {
              if (session.contains("workCsrf") && session.getString("workCsrf") != null) {
                session = session.set("csrf", session.getString("workCsrf"));
              }
              return session;
          })
        );

    ScenarioBuilder pilot = scenario("PilotWork")
      .feed(credFeeder)
      .exec(login)
      .exec(work);

    ScenarioBuilder base = scenario("BaseWork")
      .feed(credFeeder)
      .exec(login)
      .during(Duration.ofSeconds(30))
      .on(exec(work).pace(Duration.ofSeconds(1)));

    ScenarioBuilder boost = scenario("BoostWork")
      .feed(credFeeder)
      .exec(login)
      .during(Duration.ofSeconds(10))
      .on(exec(work).pace(Duration.ofSeconds(1)));

    setUp(
      pilot.injectOpen(atOnceUsers(1)),
      base.injectOpen(nothingFor(Duration.ofSeconds(5)).andThen(atOnceUsers(5))),
      boost.injectOpen(nothingFor(Duration.ofSeconds(15)).andThen(atOnceUsers(10)))
    ).protocols(httpProtocol);
  }
}
