            .on(
                pause(Duration.ofSeconds(1)).exec(workAttempt)
            )
        .exec(session -> {
            if (!session.getBoolean("workSuccess")) {
                return session.markAsFailed();
            }
            return session;
        });

    private ScenarioBuilder workScenario = scenario("WorkScenario")
        .exec(initUser)
        .exec(getLoginForm)
        .exec(postLogin)
        .exec(followLoginRedirect)
        .exec(work);

    {
        setUp(
            workScenario.injectOpen(
                constantUsersPerSec(5).during(Duration.ofSeconds(15)),
                constantUsersPerSec(15).during(Duration.ofSeconds(10)),
                constantUsersPerSec(5).during(Duration.ofSeconds(10))
            ).protocols(httpProtocol)
        ).maxDuration(Duration.ofSeconds(45));
    }
}
