import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.time.Duration;
import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL =
        System.getenv("BASE_URL") == null ? "http://127.0.0.1:8000" : System.getenv("BASE_URL");

    private static final long PHASE1_END = 15000L;
    private static final long PHASE2_END = 25000L;
    private static final long PHASE3_END = 35000L;

    private static final double RATE1 = 5.0;
    private static final double RATE2 = 15.0;
    private static final double RATE3 = 5.0;

    private static final double INTERVAL1 = 1000.0 / RATE1;
    private static final double INTERVAL2 = 1000.0 / RATE2;
    private static final double INTERVAL3 = 1000.0 / RATE3;

    private static final long[] PHASE_STARTS = {0L, PHASE1_END, PHASE2_END, PHASE3_END};
    private static final double[] PHASE_INTERVALS = {INTERVAL1, INTERVAL2, INTERVAL3};

    private static long nextFireTime(long now, int userIndex, long t0) {
        long elapsed = now - t0;
        if (elapsed >= PHASE3_END) {
            return Long.MAX_VALUE;
        }

        for (int phase = 0; phase < 3; phase++) {
            long start = PHASE_STARTS[phase];
            long end = PHASE_STARTS[phase + 1];
            double interval = PHASE_INTERVALS[phase];

            if (elapsed >= end) {
                continue;
            }

            long effective = Math.max(elapsed, start);
            double kDouble = Math.ceil((effective - start) / interval);
            long k = Math.max(0L, (long) kDouble);

            if (k % 2 != userIndex) {
                k++;
            }

            long next = start + (long) Math.floor(k * interval);
            if (next < effective) {
                next = effective;
            }

            if (next < end) {
                return next + t0;
            }
        }

        return Long.MAX_VALUE;
    }

    private ChainBuilder loginFlow() {
        return exec(
            http("login-form").get("/v2/login-form")
                .check(status().is(200))
                .check(
                    regex("<input[^>]*name\\s*=\\s*[\"']?csrf[\"']?[^>]*value\\s*=\\s*[\"']([^\"']+)[\"']").optional().saveAs("csrf1"),
                    regex("<input[^>]*value\\s*=\\s*[\"']([^\"']+)[\"'][^>]*name\\s*=\\s*[\"']?csrf").optional().saveAs("csrf2"),
                    css("input[name=csrf]", "value").optional().saveAs("csrf3"),
                    css("input[name='csrf']", "value").optional().saveAs("csrf4")
                )
        ).exec(session -> {
            String csrf = session.getString("csrf1");
            if (csrf == null) csrf = session.getString("csrf2");
            if (csrf == null) csrf = session.getString("csrf3");
            if (csrf == null) csrf = session.getString("csrf4");
            if (csrf == null) {
                throw new RuntimeException("csrf not found");
            }
            return session.set("csrf", csrf);
        }).exec(
            http("login").post("/v2/login")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .body(StringBody("{\"username\":\"${account}\",\"password\":\"bench\",\"csrf\":\"${csrf}\"}"))
                .check(status().in(200, 302))
                .check(status().saveAs("loginStatus"))
                .check(header("Location").optional().saveAs("loginLocation"))
                .check(jsonPath("$.csrf").optional().saveAs("loginCsrf"))
        ).exec(session -> {
            String status = session.getString("loginStatus");
            if ("302".equals(status)) {
                return session.set("followLogin", true);
            }
            return session.set("followLogin", false);
        }).doIf(session -> session.getBoolean("followLogin"))
            .then(
                exec(
                    http("login-follow").get(session -> session.getString("loginLocation"))
                        .check(status().is(200))
                        .check(jsonPath("$.csrf").optional().saveAs("loginCsrf"))
                )
            )
        .exec(session -> {
            String csrf = session.getString("loginCsrf");
            if (csrf != null) {
                return session.set("csrf", csrf);
            }
            return session;
        });
    }

    private ChainBuilder workCall() {
        return exec(
            http("work").post("/v2/work")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .body(StringBody("{}"))
                .check(status().in(200, 429, 401))
                .check(status().saveAs("workStatus"))
                .check(header("Retry-After").optional().saveAs("retryAfter"))
                .check(jsonPath("$.error").optional().saveAs("workError"))
                .check(jsonPath("$.csrf").optional().saveAs("workCsrf"))
        ).exec(session -> {
            String csrf = session.getString("workCsrf");
            if (csrf != null) {
                return session.set("csrf", csrf);
            }
            return session;
        });
    }

    private ChainBuilder sendWorkWith429Retries() {
        return exec(session -> session
                .set("workAttempt", 0)
                .set("workSucceeded", false)
                .set("workFinalStatus", -1))
            .asLongAs(session -> session.getInt("workAttempt") < 5)
            .on(
                exec(workCall())
                .exec(session -> {
                    int status = session.contains("workStatus") ? session.getInt("workStatus") : -1;
                    int attempt = session.getInt("workAttempt");

                    if (status == 200) {
                        return session
                            .set("workAttempt", 99)
                            .set("workSucceeded", true)
                            .set("workFinalStatus", status);
                    } else if (status == 429) {
                        int nextAttempt = attempt + 1;
                        if (nextAttempt >= 5) {
                            return session
                                .set("workAttempt", nextAttempt)
                                .set("workSucceeded", false)
                                .set("workFinalStatus", status);
                        }

                        long retryWait = 1L;
                        if (session.contains("retryAfter") && session.getString("retryAfter") != null) {
                            try {
                                retryWait = Long.parseLong(session.getString("retryAfter"));
                            } catch (Exception ignore) {
                                retryWait = 1L;
                            }
                        }

                        return session
                            .set("workAttempt", nextAttempt)
                            .set("retryWait", retryWait)
                            .set("workSucceeded", false);
                    } else {
                        return session
                            .set("workAttempt", 99)
                            .set("workSucceeded", false)
                            .set("workFinalStatus", status);
                    }
                })
                .doIf(session -> session.getInt("workAttempt") < 5 && session.contains("retryWait"))
                .then(
                    pause(session -> Duration.ofSeconds(session.getLong("retryWait")))
                )
            )
            .exec(session -> session.remove("retryWait"));
    }

    private ChainBuilder renewSession() {
        return exec(
            http("renew").post("/v2/session/renew")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .body(StringBody("{}"))
                .check(status().saveAs("renewStatus"))
                .check(jsonPath("$.csrf").optional().saveAs("renewCsrf"))
        ).exec(session -> {
            String csrf = session.getString("renewCsrf");
            if (csrf != null) {
                return session.set("csrf", csrf);
            }
            return session;
        });
    }

    private ChainBuilder workUnit() {
        return exec(sendWorkWith429Retries())
            .doIf(session -> !session.getBoolean("workSucceeded") && session.getInt("workFinalStatus") == 401)
            .then(
                exec(session -> session.set("renewAttempted", false))
                .asLongAs(session -> !session.getBoolean("renewAttempted"))
                .on(
                    exec(session -> {
                        String error = session.getString("workError");
                        if ("session".equals(error)) {
                            return session.set("renewMode", "revoked");
                        }
                        return session.set("renewMode", "expired");
                    })
                    .doIf(session -> session.getString("renewMode").equals("expired"))
                    .then(
                        exec(renewSession())
                        .exec(session -> {
                            int status = session.contains("renewStatus") ? session.getInt("renewStatus") : -1;
                            if (status == 200) {
                                return session
                                    .set("renewAttempted", true)
                                    .set("renewWorkRetry", true);
                            }
                            return session
                                .set("renewAttempted", true)
                                .set("renewWorkRetry", false)
                                .set("workSucceeded", false);
                        })
                    )
                    .doIf(session -> session.getString("renewMode").equals("revoked"))
                    .then(
                        exec(loginFlow())
                        .exec(session -> session
                            .set("renewAttempted", true)
                            .set("renewWorkRetry", true))
                    )
                )
                .doIf(session -> session.getBoolean("renewWorkRetry"))
                .then(
                    exec(workCall())
                    .exec(session -> {
                        int status = session.contains("workStatus") ? session.getInt("workStatus") : -1;
                        if (status == 200) {
                            return session
                                .set("workSucceeded", true)
                                .set("workFinalStatus", status);
                        }
                        return session
                            .set("workSucceeded", false)
                            .set("workFinalStatus", status);
                    })
                )
            )
            .exec(session -> session.set("workOk", session.getBoolean("workSucceeded")));
    }

    {
        HttpProtocolBuilder httpProtocol = http
            .baseUrl(BASE_URL)
            .disableAutoRedirect()
            .disableCaching()
            .contentTypeHeader("application/json")
            .acceptHeader("application/json")
            .userAgentHeader("Gatling-loadtest");

        ScenarioBuilder workScenario = scenario("WorkPool")
            .exec(session -> {
                long uid = session.userId();
                int userIndex = (int) ((uid - 1) % 2);
                return session
                    .set("userIndex", String.valueOf(userIndex))
                    .set("account", "bench-" + (userIndex + 1));
            })
            .exec(loginFlow())
            .rendezVous(2)
            .exec(session -> {
                long t0 = System.currentTimeMillis();
                return session
                    .set("t0", t0)
                    .set("workActive", true);
            })
            .asLongAs(session -> session.getBoolean("workActive"))
            .on(
                exec(session -> {
                    long now = System.currentTimeMillis();
                    long t0 = session.getLong("t0");
                    int userIndex = Integer.parseInt(session.getString("userIndex"));
                    long next = nextFireTime(now, userIndex, t0);

                    if (next == Long.MAX_VALUE) {
                        return session.set("workActive", false);
                    }

                    long pauseMs = Math.max(0L, next - now);
                    return session.set("nextPause", pauseMs);
                })
                .doIf(session -> session.getBoolean("workActive"))
                .then(
                    pause(session -> Duration.ofMillis(session.getLong("nextPause")))
                )
                .doIf(session -> session.getBoolean("workActive"))
                .then(
                    exec(workUnit())
                )
            );

        setUp(
            workScenario.injectOpen(atOnceUsers(2))
        ).protocols(httpProtocol);
    }
}
